const root=document.querySelector('#app');const fmt=n=>Math.floor(n).toLocaleString('ja-JP');
let stopFrames=null;
let profile=freshProfile(),selected=0,selectedMachine=0,floorArt=null,detailArt=null,endlessMode=false,game=null,physics=null,machine=null,battle=null,moonTraces=null,rushScreen=null,reelDisplay=null,viewportFit=null,auto=true,held=false,manual=false,power=.5,angle=0,speed=1,last=0,accumulator=0,fireClock=0,muzzleClock=0,pendingExtras=0,sound=true,modal=null,noticeTimer=null,saveError=false;
try{const {value}=await Preferences.get({key:'tsukikage-profile-v1'});if(value){const p=JSON.parse(value);profile.tickets=Number.isFinite(p.tickets)?Math.max(0,Math.floor(p.tickets)):0;profile.unlocked=Math.min(3,Math.max(1,Math.floor(p.unlocked)||1));profile.best=Array.isArray(p.best)?p.best.slice(0,3).map(v=>Math.min(10,Math.max(0,Number(v)||0))):[0,0,0];for(const u of UPGRADES)profile.upgrades[u.id]=Math.min(u.max,Math.max(0,Math.floor(p.upgrades?.[u.id])||0));}}catch{saveError=true;}
let saves=Promise.resolve();function save(){const value=JSON.stringify(profile);saves=saves.then(()=>Preferences.set({key:'tsukikage-profile-v1',value})).catch(()=>{saveError=true;notice('保存に失敗しました。端末の空き容量をご確認ください。');});return saves;}
function beep(){sfx.play('select');}
function header(){return `<header class="masthead"><div class="brand">月影機関<small>TSUKIKAGE CHRONICLES</small></div><div class="edition">PACHINKO ROGUELITE · PROTOTYPE 01</div><div class="currency">TICKET <b>${fmt(profile.tickets)}</b></div></header>`;}
async function home(){stopFrames?.();stopFrames=null;floorArt?.destroy();floorArt=null;detailArt?.destroy();detailArt=null;moonTraces?.dispose();moonTraces=null;sfx.stop();viewportFit?.dispose();viewportFit=null;disposeTitle(document.querySelector('#cinemaTitle'));game=null;reelDisplay?.dispose();reelDisplay=null;rushScreen?.dispose();rushScreen=null;battle?.dispose();battle=null;machine?.dispose();machine=null;closeModal();
 root.innerHTML=`<main class="shell floor-shell"><section class="arcade-floor"><nav class="floor-nav" aria-label="フロア"><button class="floor-arrow" disabled aria-label="前のフロア">◀</button><div><strong>1F</strong><span>0枚</span></div><button class="floor-arrow" disabled aria-label="次のフロア">▶</button></nav><div class="floor-grid-wrap"><div class="floor-art-host" id="floorArt"></div><div class="floor-grid" id="machineGrid">${FLOOR_ONE.map((item,index)=>`<button class="floor-machine" data-unit="${index}" data-kind="${item.kind}" aria-label="${String(item.unit).padStart(2,'0')}番台" ${item.kind==='dummy'?'disabled':''}><span class="floor-machine-art"></span></button>`).join('')}</div></div></section></main>`;
 floorArt=await mountFloorArt(document.querySelector('#floorArt'));
 root.querySelectorAll('[data-kind="main"]').forEach(el=>el.onclick=()=>{selectedMachine=+el.dataset.unit;showMachineDetails();});
}
async function showMachineDetails(){
 const item=FLOOR_ONE[selectedMachine];if(item.kind!=='main')return;
 floorArt?.destroy();floorArt=null;
 const spec=MACHINE_SPECS[0];
 root.innerHTML=`<main class="shell floor-shell machine-detail-page">${header()}<section class="arcade-floor"><button id="backToFloor" class="secondary detail-back">← フロア一覧</button><div class="detail-heading"><div><div class="eyebrow">FLOOR 01 · CABINET ${String(item.unit).padStart(2,'0')}</div><h1>${item.name}</h1><p>同じ機種の台です。釘の配置はこの台専用です。</p></div><div class="floor-ticket"><span>プレイ料金</span><b>0</b><small>枚</small></div></div><div class="machine-detail-grid"><div class="detail-art-frame"><div id="detailCabinetArt" class="detail-cabinet-art"></div><span>個体釘配置 · ${String(item.unit).padStart(2,'0')}</span></div><section class="detail-spec-panel"><h2>機種スペック</h2><div class="detail-stat"><span>通常時 大当り確率</span><b>1/${spec.normal.odds}</b></div><div class="detail-stat"><span>RUSH中 大当り確率</span><b>1/${Number(spec.rightDraw.odds.toFixed(3))}</b></div><div class="detail-stat"><span>RUSH</span><b>${spec.rightDraw.spins}回転</b></div><div class="detail-stat"><span>大当りラウンド</span><b>${spec.normal.rounds.join(' / ')}R</b></div><div class="detail-stat"><span>釘の本数</span><b>63本 · 各台共通</b></div><div class="detail-history"><div><b>遊技記録</b><span>プレイ後に表示</span></div><svg viewBox="0 0 240 54" role="img" aria-label="遊技記録グラフ。まだ記録はありません"><path d="M2 45H238M2 27H238M2 9H238"/><path class="empty-trace" d="M4 40H236"/></svg></div><button id="playMachine" class="primary detail-play">▶ プレイ開始 · 0枚</button></section></div><p class="floor-footnote">表示スペックは試作値です。釘配置の個体差は遊技の玉の流れに反映されます。</p></section><footer class="bottom-note"><span>月影機関アーケード / LOCAL BUILD</span><span>FLOOR 01 · CABINET ${String(item.unit).padStart(2,'0')}</span></footer></main>`;
 detailArt=await mountCabinetArt(document.querySelector('#detailCabinetArt'),selectedMachine,item.kind);
 document.querySelector('#backToFloor').onclick=home;
 document.querySelector('#playMachine').onclick=()=>{selected=0;endlessMode=false;start(false);};
}
function showModal(html){closeModal();held=false;modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="ゲームメニュー">${html}</section>`;document.body.append(modal);modal.querySelector('button')?.focus();}
function closeModal(){modal?.remove();modal=null;}
function guide(){showModal(`<div class="eyebrow">HOW TO PLAY</div><h2>一玉から、次の月へ。</h2><p class="intro">① 自動発射でスタート。AUTOを切ると、発射ボタンを押している間だけ玉を打ちます。<br><br>② 入賞で持ち玉を増やし、突破ラインに達すると次のステージへ。発射で減った玉も判定に含まれます。<br><br>③ スキルを選ぶと次のステージへ。大当り賞球は×1.5、必要な持ち玉増加は×2、発射速度は×${FIRE_GROWTH}（最大${fmt(MAX_FIRE_RATE)}発／分）になります。大当りのステージ倍率は開始時に固定し、上がった倍率は次の大当りに適用します。通常入賞の賞球はステージ・コース倍率では増えません。<br><br>④ チケットは出玉の節目とステージ突破で自動獲得・保存。ポーズやスキル選択から「精算して強化へ」で終了し、すぐに永続強化できます。<br><br>下限はステージ開始時の持ち玉−初期持ち玉（最低0玉）。下限未満、または0玉の状態が3秒続くと終了します。下限以上かつ1玉以上に回復するとカウントはリセット。ポーズ・スキル選択中は停止します。</p><button id="close" class="primary">わかりました</button>`);document.querySelector('#close').onclick=closeModal;}
function showUpgrades(){showModal(`<div class="eyebrow">PERMANENT UPGRADE</div><h2>機関を強化する</h2><p class="intro">全コースに共通の強化です。<br>所持チケット <b style="color:#e2c695">${fmt(profile.tickets)}枚</b></p>${UPGRADES.map(u=>{const lv=profile.upgrades[u.id]||0,cost=upgradeCost(lv);return `<div class="upgrade-row"><div><strong>${u.name}</strong><span class="level">Lv.${lv}/${u.max}</span><p>${u.description}</p></div><button data-up="${u.id}" ${lv>=u.max||profile.tickets<cost?'disabled':''}>${lv>=u.max?'MAX':`${cost}枚で強化`}</button></div>`;}).join('')}<button id="close" class="primary">コース選択へ</button>`);modal.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{const u=UPGRADES.find(u=>u.id===b.dataset.up),lv=profile.upgrades[u.id]||0,cost=upgradeCost(lv);if(lv>=u.max||profile.tickets<cost)return;profile.tickets-=cost;profile.upgrades[u.id]=lv+1;save();beep(880,.15);showUpgrades();});document.querySelector('#close').onclick=home;}
let loadingController=null;
async function start(practice){
 if(loadingController)return;
 const controller=new AbortController();loadingController=controller;closeModal();sfx.stop();sfx.unlock();
 let preparedMachine=null,preparedTitle=null;
 const screen=mountLoadingScreen(root,{onCancel:()=>{controller.abort();loadingController=null;home();}});
 try{
  await prepareGameAssets({signal:controller.signal,onProgress:value=>{if(!controller.signal.aborted)screen.progress({complete:value.complete,total:value.total+3});}});
  let prepared=GAME_IMAGES.length;const report=()=>{if(!controller.signal.aborted)screen.progress({complete:++prepared,total:GAME_IMAGES.length+3});};
  preparedMachine=await Machine.create(document.createElement("div"),new Physics(selected,FLOOR_ONE[selectedMachine]?.pegSeed??0),{course:selected,signal:controller.signal,onProgress:report});
  preparedTitle=await TitleSculpture.create(document.createElement("div"),preparedMachine.glyphData);report();
  if(controller.signal.aborted){preparedTitle.dispose();preparedMachine.dispose();return;}
  await startPrepared(practice,preparedMachine,preparedTitle);
  if(document.hidden&&game?.phase==='playing')pause();
 }catch(error){
  preparedTitle?.dispose();preparedMachine?.dispose();
  if(controller.signal.aborted)return;
  controller.abort();console.error(error);screen.error(()=>start(practice));
 }finally{if(loadingController===controller)loadingController=null;}
}
async function startPrepared(practice,preparedMachine,preparedTitle){stopFrames?.();stopFrames=null;sfx.stop();viewportFit?.dispose();viewportFit=null;sfx.volume=.65;sfx.impactLevel=1;if(sfx.master)sfx.master.gain.value=.65;sfx.unlock();closeModal();auto=true;held=false;manual=false;power=.5;angle=0;speed=1;accumulator=0;fireClock=0;muzzleClock=0;pendingExtras=0;game=new Game(profile,selected,Math.random,{endless:endlessMode&&!practice});game.practice=practice;physics=preparedMachine.physics;power=physics.normalPower??.57;root.innerHTML=`<main class="shell game-shell immersive">${header()}<div class="game-layout"><section class="machine-column">${dataCounterMarkup({practice,endless:game.endless,sound,debug:DEBUG_ENABLED})}<div class="board-wrap"><div class="board-canvas" id="canvas"></div><div class="lcd" id="lcd"><div id="battleCanvas" class="battle-canvas"></div><div class="anime-still"><img src="${GUARDIAN_ART}" alt=""></div><div class="cinema-overlay" id="cinema"><small id="cinemaKicker"></small><strong id="cinemaTitle"></strong><div class="cutin"><img src="${GUARDIAN_ART}" alt="月影機関の守護者"></div><p id="cinemaLine"></p></div><div class="lcd-title">${game.course.name}</div><div class="reels" id="reels"><span>3</span><span>7</span><span>1</span></div><div class="holds" id="holds" aria-label="保留0個、最大5個">${Array.from({length:5},()=>'<i></i>').join('')}</div></div><div class="board-banner" id="banner"></div><div class="shot-warning" id="shotWarning" hidden>左打ちに戻してください<small>発射の強さを下げてください</small></div><div class="zero-warning" id="zero" hidden></div></div><div class="control-panel"><div class="shoot-row"><button class="fire" id="fire">自動発射中</button><button id="auto" class="auto on">AUTO<br><b>ON</b></button></div><div class="tuning"><span>発射調整</span><button id="manual">自動</button><span id="powerLabel">強さ・方向をおまかせ</span></div><div class="manual-controls" id="manualControls" hidden><label>強さ<input id="power" type="range" min="0" max="100" value="${Math.round(power*100)}" aria-label="発射の強さ"></label><label>発射角の微調整<input id="angle" type="range" min="-100" max="100" value="0" aria-label="発射の方向"></label></div><div class="stage-rules" id="stageRules"></div><div class="ticket-progress" id="ticketProgress" role="status"></div><div class="mobile-session" id="mobileSession"></div></div></section><aside class="side-panel"><div class="eyebrow">CHAPTER ${String(selected+1).padStart(2,'0')}</div><h2>${game.course.name}</h2><p class="subtitle">${game.course.subtitle}</p><div class="session-stat"><span>累計獲得出玉</span><b id="total">0</b></div><div class="session-stat"><span>大当り回数</span><b id="jackpots">0</b></div><div class="session-stat"><span>抽選 / 待機</span><b id="draws">0 / 0</b></div><div class="side-section"><div class="side-label">YOUR BUILD</div><div id="build" class="skill-chips"><p class="empty-copy">ステージを突破すると、<br>新しい力を選べます。</p></div></div><div class="side-section"><p class="empty-copy">玉は釘に弾かれ、入賞口へ。<br>持ち玉が続く限り、<br>次のステージを目指せます。</p></div>${practice?'<button id="support" class="secondary" style="margin-top:24px">試遊サポート</button>':''}<p class="screenshot-hint">発射・賞球・目標の数値は試作設定です。</p></aside></div></main>`;
 const board=document.querySelector('.board-wrap'),lcd=document.querySelector('#lcd');board.style.setProperty('--machine-aspect',`${MACHINE_VIEW.width} / ${MACHINE_VIEW.height}`);board.style.setProperty('--machine-ratio',MACHINE_VIEW.width/MACHINE_VIEW.height);for(const [key,value] of Object.entries({left:MACHINE_VIEW.lcd.x/MACHINE_VIEW.width,top:MACHINE_VIEW.lcd.y/MACHINE_VIEW.height,width:MACHINE_VIEW.lcd.width/MACHINE_VIEW.width,height:MACHINE_VIEW.lcd.height/MACHINE_VIEW.height}))lcd.style[key]=`${value*100}%`;lcd.style.borderRadius=`${MACHINE_VIEW.lcd.radius/MACHINE_VIEW.lcd.width*100}% / ${MACHINE_VIEW.lcd.radius/MACHINE_VIEW.lcd.height*100}%`;
 try{machine=preparedMachine;machine.mount(document.querySelector('#canvas'));preparedTitle.mount(document.querySelector('#cinemaTitle'));battle=new Battle(document.querySelector('#battleCanvas'));rushScreen=mountRushScreen(document.querySelector('#lcd'));reelDisplay=mountReelDisplay(document.querySelector('#reels'));moonTraces=mountMoonTraces(document.querySelector('.board-wrap'),document.querySelector('#lcd'),physics,MACHINE_VIEW);viewportFit=mountViewportFit(document.querySelector('.game-shell'));}catch(e){game=null;root.innerHTML=`<div class="error">3D表示を開始できませんでした。WebGL対応のブラウザ・端末でお試しください。<br><button id="back" class="secondary">戻る</button></div>`;document.querySelector('#back').onclick=home;console.error(e);return;}
 document.querySelector('#debug')?.addEventListener('click',()=>{if(game.phase!=='playing')return;game.pause();sfx.stop();debugPanel(game,sfx,{close:()=>{},resume:()=>game.resume(),events:processEvents,notice});});document.querySelector('#pause').onclick=pause;document.querySelector('#specs').onclick=showSpecs;document.querySelector('#chart').onclick=showChart;document.querySelector('#liveBalance').onclick=showChart;document.querySelector('#viewMode').onclick=()=>{const shell=document.querySelector('.game-shell');shell.classList.toggle('immersive');viewportFit?.refresh();document.querySelector('#viewMode').textContent=shell.classList.contains('immersive')?'全体':'拡大';};document.querySelector('#sound').onclick=()=>{sound=!sound;sfx.setEnabled(sound);document.querySelector('#sound').textContent=`音 ${sound?'ON':'OFF'}`;beep();};document.querySelector('#auto').onclick=()=>{auto=!auto;held=false;updateControls();};const fire=document.querySelector('#fire');fire.onpointerdown=e=>{e.preventDefault();if(game.phase!=='playing')return;if(auto){auto=false;updateControls();}held=true;fire.setPointerCapture(e.pointerId);};fire.onpointerup=fire.onpointercancel=()=>held=false;document.querySelector('#manual').onclick=()=>{manual=!manual;document.querySelector('#manualControls').hidden=!manual;viewportFit?.refresh();document.querySelector('#manual').textContent=manual?'手動':'自動';document.querySelector('#powerLabel').textContent=manual?'強さと発射角を調整':'強さ・方向をおまかせ';};document.querySelector('#power').oninput=e=>power=+e.target.value/100;document.querySelector('#angle').oninput=e=>angle=+e.target.value/100;document.querySelector('#support')?.addEventListener('click',support);notice('AUTO ON ── 遊技を開始します');updateHUD();last=performance.now();stopFrames=startFrameLoop(frame);}
function updateControls(){const a=document.querySelector('#auto');if(!a)return;a.classList.toggle('on',auto);a.innerHTML=`AUTO<br><b>${auto?'ON':'OFF'}</b>`;document.querySelector('#fire').textContent=auto?'自動発射中':'押している間 発射';}
const holdVisual={game:null,mode:null,ids:[]};
function holdTone(record){
 let seed=Math.imul(record.id^0x9e3779b9,0x85ebca6b)>>>0;seed=(seed^(seed>>>13))>>>0;
 const roll=seed%997;
 return record.baseWin?(roll<650?'gold':roll<830?'silver':'blue'):roll===0?'gold':roll<42?'silver':'blue';
}
function updateHolds(){
 const holds=document.querySelector('#holds'),mode=game.rush?'rush':'normal',records=game.acceptedDraws,ids=records.map(record=>record.id);
 const previous=holdVisual.game===game&&holdVisual.mode===mode?holdVisual.ids:[];
 holds.setAttribute('aria-label',`保留${ids.length}個、最大5個`);
 [...holds.children].forEach((dot,index)=>{
  const record=records[index],id=record?.id,was=previous.indexOf(id),tone=record&&game.time-record.acceptedAt>=.55?holdTone(record):'blue';
  const changedTone=record&&dot.dataset.holdId===String(id)&&dot.dataset.tone!==tone;
  const action=id===undefined?(previous[index]!==undefined?'hold-depart':null):was<0?'hold-arrive':was>index?'hold-step':changedTone?'hold-transform':null;
  dot.style.setProperty('--hold-index',index);
  dot.classList.toggle('filled',id!==undefined);
  if(record){dot.dataset.holdId=String(id);dot.dataset.tone=tone;}else{delete dot.dataset.holdId;delete dot.dataset.tone;}
  if(action){dot.classList.remove('hold-arrive','hold-step','hold-depart','hold-transform');void dot.offsetWidth;dot.classList.add(action);}
  dot.onanimationend=()=>dot.classList.remove('hold-arrive','hold-step','hold-depart','hold-transform');
 });
 holdVisual.game=game;holdVisual.mode=mode;holdVisual.ids=ids;
}
function notice(text){const n=document.querySelector('#banner');if(!n)return;n.textContent=text;n.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.classList.remove('show'),2200);}
function cashOut(){closeModal();game.finish('retired');processEvents();home();showUpgrades();}
function pause(){if(game.phase!=='playing')return;sfx.stop();game.pause();held=false;showModal(`<div class="eyebrow">PAUSED</div><h2>ひと息、月を眺める。</h2><p class="intro">すべての進行を一時停止しています。</p><p class="intro">${ticketStatus()}<br>精算すると今回の遊技は終了し、獲得したチケットで強化できます。</p><div class="skill-chips">${Object.entries(game.skills).map(([id,lv])=>`<span class="chip">${SKILLS.find(s=>s.id===id).name} Lv.${lv}</span>`).join('')||'<p class="empty-copy">スキルはまだ取得していません。</p>'}</div><button id="resume" class="primary">遊技を再開</button>${game.practice?'<button id="support" class="secondary" style="width:100%;margin-top:10px">試遊サポート</button>':''}<button id="cashOut" class="secondary cash-out">精算して強化へ</button>`);document.querySelector('#resume').onclick=()=>{closeModal();game.resume();};modal.querySelector('#support')?.addEventListener('click',support);document.querySelector('#cashOut').onclick=cashOut;}
function showSpecs(){if(!game)return;const resume=game.phase==='playing';game.pause();const m=game.machine,r=m.rightDraw;const weightsText=weights=>m.normal.rounds.map((round,i)=>`${round}R：${Math.round(weights[i]/weights.reduce((a,b)=>a+b,0)*100)}%`).join(' / ');showModal(`<div class="eyebrow">${game.course.name}</div><h2>台の仕様</h2><p class="intro">通常時は左打ち。大当り・RUSH中は右打ちです。自動調整の右打ちは玉の詰まりを避けて最大600発／分に調整します。</p><div class="result-detail"><span>通常時の大当り</span><b>1/${m.normal.odds}</b></div><div class="result-detail"><span>初当りの振分け</span><b>${weightsText(m.normal.weights)}</b></div><div class="result-detail"><span>初当りからRUSHへ</span><b>4R：${Math.round(m.rushEntry.fourRoundRate*100)}% / 6R・10R：確定</b></div><div class="result-detail"><span>RUSH</span><b>${r.spins}回転・1/${Number(r.odds.toFixed(3))}（${r.spins}回転内の当選率 約${(100*(1-(1-1/r.odds)**r.spins)).toFixed(1)}%）</b></div><div class="result-detail"><span>RUSH中の振分け</span><b>${r.payouts?r.payouts.map(p=>`${p.amount}玉：${Math.round(p.weight/r.weights.reduce((a,b)=>a+b,0)*100)}%`).join(' / '):weightsText(r.weights)}</b></div><div class="result-detail"><span>基礎賞球（一般 / ヘソ / 電チュー / 大入賞口）</span><b>${m.prizes.normal} / ${m.prizes.start} / ${m.prizes.rush} / ${r.payouts?'10または15':m.prizes.bonus}玉</b></div><div class="result-detail"><span>1ラウンド</span><b>${m.countLimit}カウント / 最大${m.openSeconds}秒</b></div><p class="intro">RUSHは当るたび、大当り消化後に${r.spins}回転へ戻ります。当り中のR昇格は、当選済みの最終ラウンド数の告知です。<br>保留は各5個。通常保留はRUSH終了まで待機します。RUSHの受付は残り回転数までです。保留ランプは青・白・金に変化することがあり、色は期待度の演出で当り確定ではありません。<br>賞球にはコース倍率×${game.course.scale}・ステージ倍率×${game.payoutMultiplier.toFixed(2)}と強化が加わります。${game.jackpot?`現在の大当りは開始時の×${game.jackpot.payoutMultiplier.toFixed(2)}で固定。`:""}大当りのステージ倍率は開始から終了まで固定し、上がった倍率は次の大当りに適用します。通常入賞の賞球はステージ・コース倍率では増えません。天井は通常時の救済として、大当り後${game.rules.pityLimit}回転が基準です。</p><button id="closeSpecs" class="primary">遊技に戻る</button>`);document.querySelector('#closeSpecs').onclick=()=>{closeModal();if(resume)game.resume();};}
function accountingDetails(){const a=game.accounting;return `<div class="result-detail"><span>台の基礎賞球</span><b>${fmt(a.basePrize)}玉</b></div><div class="result-detail"><span>ゲーム補正・獲得加算</span><b>${fmt(a.gamePrize)}玉</b></div><div class="result-detail"><span>発射消費</span><b>−${fmt(a.spent)}玉</b></div><div class="result-detail"><span>補給 / 返却</span><b>${fmt(a.supply)} / ${fmt(a.returned)}玉</b></div>${a.debugAdjustment?`<div class="result-detail"><span>デバッグ調整</span><b>${a.debugAdjustment>0?'+':''}${fmt(a.debugAdjustment)}玉</b></div>`:''}`;}
function showChart(){if(!game)return;sfx.stop();const resume=game.phase==='playing';game.pause();showModal(`<h2>差玉グラフ</h2><div class="result-detail"><span>累計回転数</span><b id="totalSpins">${fmt(game.draws)}回転</b></div><div class="result-detail"><span>大当り後</span><b>${fmt(game.pityCount)}回転</b></div><div class="result-detail"><span>天井まで</span><b>${fmt(Math.max(0,game.rules.pityLimit-game.pityCount))}回転</b></div>${balanceChart(game)}${accountingDetails()}<button id="closeChart" class="primary">遊技に戻る</button>`);document.querySelector('#closeChart').onclick=()=>{closeModal();if(resume)game.resume();};}
function support(){if(!game.practice)return;sfx.stop();game.pause();showModal(`<div class="eyebrow">PLAYTEST · 報酬保存なし</div><h2>試遊サポート</h2><p class="intro">待たずに演出とゲームの流れを確認できます。</p><label class="preview-label">交戦シーン<select id="previewScene">${SCENES.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><label class="preview-label">展開<select id="previewPattern">${PATTERNS.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label class="preview-label">戦い方<select id="previewBuild"><option value="balanced">基本・月断一閃</option><option value="assault">援護射撃・追加玉ビルド</option><option value="fortify">装備防壁・入賞強化ビルド</option><option value="counter">受け流し・反撃ビルド</option></select></label><label class="preview-label">リーチ文字<select id="previewColor"><option value="auto">抽選におまかせ</option><option value="normal">通常色</option><option value="red">赤（チャンスアップ）</option></select></label><button id="previewReach" class="primary">この演出を再生</button><div class="training-options"><button id="testKyuin" class="secondary">キュイン音を試す</button><button id="testWin" class="secondary">戦闘演出を試す（勝利）</button><button id="testLose" class="secondary">戦闘演出を試す（敗北）</button><button id="testHolds" class="secondary">始動入賞を6個試す</button><button id="testBonus" class="secondary">大当りを開始</button><button id="testStage" class="secondary">次のスキル選択へ</button><button id="testStock" class="secondary">持ち玉 ＋500</button><button id="testSpeed" class="secondary">進行速度 ${speed}× → ${speed===1?3:1}×</button><button id="testEnd" class="secondary">リザルトを確認</button></div><button id="resume" class="primary">遊技に戻る</button>`);const act=fn=>()=>{closeModal();game.resume();fn();processEvents();};document.querySelector('#previewReach').onclick=()=>{const sceneId=document.querySelector('#previewScene').value,pattern=document.querySelector('#previewPattern').value,color=document.querySelector('#previewColor').value,buildStyle=document.querySelector('#previewBuild').value;closeModal();game.resume();sfx.stop();game.presentation=null;game.jackpot=null;game.queue=0;game.spinActive=false;game.stopTimer=0;const win=PATTERNS.find(p=>p.id===pattern).win;game.beginPresentation(win,true,{sceneId,pattern,color,buildStyle});processEvents();};for(const [id,win] of [['testWin',true],['testLose',false]])document.querySelector('#'+id).onclick=act(()=>{if(!game.beginPresentation(win,true,{pattern:win?'awakening':'defeat',sceneId:'eclipse'}))notice('現在の演出・大当りの終了後に試せます');});document.querySelector('#testKyuin').onclick=()=>{sound=true;sfx.setEnabled(true);document.querySelector('#sound').textContent='音 ON';sfx.stop();sfx.play('kyuin');};document.querySelector('#testHolds').onclick=act(()=>{for(let i=0;i<6;i++)game.hit({gold:false,large:false,hits:0,after:false},'start',4);});document.querySelector('#testBonus').onclick=act(()=>game.startJackpot());document.querySelector('#testStage').onclick=act(()=>{game.award(Math.max(0,game.target-game.stock));game.checkStage();});document.querySelector('#testStock').onclick=act(()=>game.addStock(500));document.querySelector('#testSpeed').onclick=act(()=>speed=speed===1?3:1);document.querySelector('#testEnd').onclick=act(()=>game.finish('lost'));document.querySelector('#resume').onclick=act(()=>{});}
function skillChoice(){showModal(`<div class="eyebrow">STAGE ${String(game.cleared).padStart(2,'0')} CLEAR</div><h2>次の一手を、選ぶ。</h2><p class="intro">玉と大当りの進行は停止中です。<br>1つ選んでステージ${game.stage+1}へ。<br>通常賞球は据え置き・大当り賞球×${game.rules.payoutGrowth}・必要増加×${game.rules.growth}・発射速度×${FIRE_GROWTH}（上限${fmt(MAX_FIRE_RATE)}発／分）。${game.jackpot?"<br>進行中の大当りは開始時の賞球倍率を維持します。":""}<br>${ticketStatus()}</p>${!game.choices.length?'<p class="intro">すべてのスキルが最大になりました。</p><button id="continueStage" class="primary">次のステージへ</button>':''}${game.choices.map(s=>{const lv=game.skills[s.id]||0;return `<button class="skill-card" data-skill="${s.id}"><small>${s.category} · ${lv?'LEVEL UP':'NEW SKILL'}</small><strong>${s.name}<b>Lv.${lv+1}</b></strong><p>${s.description}<br><b>${s.values[lv]}${s.unit}</b></p></button>`;}).join('')}<button id="skillCashOut" class="secondary cash-out">精算して強化へ</button>`);modal.querySelector('#skillCashOut').onclick=cashOut;modal.querySelector('#continueStage')?.addEventListener('click',()=>{closeModal();game.selectSkill(null);processEvents();});modal.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{closeModal();game.selectSkill(b.dataset.skill);processEvents();beep(880,.12);});}
function showResult(){const r=game.result;if(game.claimResult(profile))save();showModal(`<div class="eyebrow">${r.reason==='clear'?'COURSE CLEAR':r.reason==='retired'?'RETIRED':'RESULT'}</div><h2>${r.reason==='clear'?'月の向こうへ。':r.reason==='retired'?'また、次の一玉へ。':'この一歩が、次の力に。'}</h2><p class="intro">${game.course.name} / ${r.cleared}ステージ突破${r.debug?'<br>デバッグ使用：新しい報酬・解放・記録は保存されません。獲得済みチケットは保持します。':r.endless?'<br>無限モード：チケット獲得・通常コースの解放はありません。':r.practice?'<br>試遊モードのため報酬・解放は保存されません。':''}</p>${balanceChart(game)}${accountingDetails()}<div class="result-numbers"><strong>＋${fmt(r.tickets)}</strong> <span>今回の獲得合計（受取済み含む）</span></div>${r.tickets?`<div class="result-detail"><span>獲得出玉による報酬</span><b>${fmt(r.reward.payout)}枚</b></div><div class="result-detail"><span>ステージ突破ボーナス</span><b>${fmt(r.reward.stages)}枚</b></div><div class="result-detail"><span>永続強化による追加</span><b>${fmt(r.reward.upgrade)}枚</b></div>`:`<p class="intro">${ticketStatus()}</p>`}<div class="result-detail"><span>所持チケット</span><b id="resultTickets">${fmt(profile.tickets)}枚</b></div><div class="result-detail"><span>累計獲得出玉</span><b>${fmt(r.total)}玉</b></div><div class="result-detail"><span>大当り</span><b>${game.jackpots}回</b></div><button id="resultUpgrade" class="primary">永続強化へ</button><button id="home" class="secondary cash-out">準備画面へ</button>`);document.querySelector('#home').onclick=home;document.querySelector('#resultUpgrade').onclick=()=>{home();showUpgrades();};}
function processEvents(){if(!game)return;for(const e of game.events.splice(0)){moonTraces?.receive(e,game);if(e.type==='tickets'&&game.claimTickets(profile)){save();const currency=document.querySelector('.currency b');if(currency)currency.textContent=fmt(profile.tickets);}if(e.type==='extra')pendingExtras++;if(e.type==='payout')sfx.play(e.kind==='bonus'?'payout':e.kind==='start'?'start':'pocket');if(e.type==='draw'&&!e.win)sfx.play('stop');if(e.type==='clear'){sfx.stop();sfx.play('clear');}if(e.type==='jackpot'){notice(`${game.jackpot.displayRounds}R大当り ── 右打ちしてください`);sfx.play('open');}if(e.type==='roundsRevealed')sfx.play('roundReveal');if(e.type==='rushChallengeStart')sfx.play('rushChallenge');if(e.type==='rushEntryResult'&&e.win)sfx.play('breakthrough');if(e.type==='rushReset')sfx.play('rushReset');if(e.type==='bonusEnd'&&!game.rush)notice('大当り終了 ── 左打ちに戻してください');if(e.type==='rushStart'){notice(`月影RUSH ── ${game.rush.remaining}回転のチャンス`);sfx.play('rushStart');}if(e.type==='rushEnd')notice('RUSH終了 ── 左打ちに戻してください');if(e.type==='stage')notice(`STAGE ${game.stage} ── 次の月へ`);if(e.type==='finish'){sfx.stop();showResult();}}if(game.phase==='skill'&&!modal)skillChoice();}
let lastBeat='';function updateCinema(){const p=timeline(game),beat=p?reachBeat(p):null,lcd=document.querySelector('#lcd');lcd.classList.toggle('cinematic',!!p);lcd.dataset.beat=beat?.id||'idle';lcd.dataset.cutin=String(beat?.id==='revival');lcd.dataset.reachColor=p?.reachColor||'normal';sfx.quiet=!!beat;if(!beat){lastBeat='';return;}document.querySelector('#cinemaKicker').textContent=beat.id==='resolve'?(p.win?'大当り / MOONLIGHT VICTORY':''):'TSUKIKAGE / BATTLE REACH';const label=beat.title;document.querySelector('#cinemaTitle').hidden=!label;const tone=['reach','warning','enemy','crisis'].includes(beat.id)?p.reachColor:beat.id==='resolve'&&p.win?'rainbow':['awakening','strike'].includes(beat.id)?'ice':['warning','enemy','crisis'].includes(beat.id)?'red':'gold';if(label)updateTitle(document.querySelector('#cinemaTitle'),label,tone,p.t-beat.from);const cutinBeat=lcd.dataset.cutin==='true',cutinU=(p.t-beat.from)/(beat.to-beat.from),cutinOpacity=cutinBeat?Math.min(1,Math.max(0,(cutinU-.18)/.1))*Math.min(1,Math.max(0,(1-cutinU)/.16)):1;document.querySelector('#cinemaTitle').style.opacity=cutinOpacity;document.querySelector('#cinemaLine').style.opacity=cutinOpacity;document.querySelector('#cinemaLine').textContent=beat.line;const key=p.id+beat.id;if(key!==lastBeat){lastBeat=key;sfx.cinematic(beat,p);}}
function ticketStatus(){
 const earned=`今回 ＋${fmt(game.ticketEstimate)}枚獲得 · 所持 ${fmt(profile.tickets)}枚`;
 if(game.debug)return `${earned} · デバッグ中は追加獲得なし`;
 if(game.practice)return '試遊モード：チケット対象外';
 if(game.endless)return '無限モード：チケット対象外';
 if(!game.total)return game.result?'賞球なしのため獲得0枚です。':'チケット 0枚 · 賞球を得ると1枚から獲得';
 return earned;
}
let lastChartSecond=-1;let hudTick=0;function updateHUD(){if(!game||!document.querySelector('#stock'))return;const live=document.querySelector('#liveBalance');const chartKey=Math.floor(game.time)+':'+game.stock;if(live&&live.dataset.value!==chartKey){live.dataset.value=chartKey;live.innerHTML=balanceChart(game,true);}const ticketProgress=document.querySelector('#ticketProgress'),ticketText=ticketStatus();if(ticketProgress.textContent!==ticketText)ticketProgress.textContent=ticketText;document.querySelector('#stock').textContent=fmt(game.stock);updateDataCounter(document.querySelector('.machine-dashboard'),game);document.querySelector('#progressText').textContent=fmt(game.target);document.querySelector('#stageRules').textContent=`下限 ${fmt(game.lowerBorder)}玉 · 大当り賞球 ×${Number((game.course.scale*(game.jackpot?.payoutMultiplier??game.payoutMultiplier)).toFixed(2))}${game.jackpot?"（大当り固定）":""} · ${fmt(game.fireRate)}発/分`;document.querySelector('#target').textContent='玉';document.querySelector('#stage').textContent=String(game.stage).padStart(2,'0');document.querySelector('#progressBar').style.width=`${Math.max(0,Math.min(100,game.progress/game.requiredGain*100))}%`;const shot=shotSettings(game,physics,{manual,power,angle}),status=shotStatus(game,physics,shot,{assisted:!manual});document.querySelector('#shotWarning').hidden=!manual||!status.warning;const j=game.jackpot;rushScreen?.update(game);document.querySelector('#lcd').classList.toggle('jackpot',!!j);updateHolds();const zero=document.querySelector('#zero');zero.hidden=!game.belowBorder||game.phase==='result';zero.textContent=`下限 ${fmt(game.lowerBorder)}玉 · 終了まで ${(Math.max(0,3-game.zeroTime)).toFixed(1)}秒`;document.querySelector('#total').textContent=fmt(game.total);document.querySelector('#jackpots').textContent=game.jackpots;document.querySelector('#draws').textContent=`${game.draws} / ${game.queue}`;document.querySelector('#mobileSession').textContent=`累計 ${fmt(game.total)}玉　・　大当り ${game.jackpots}回　・　保留 ${game.queue}/5`;document.querySelector('#build').innerHTML=Object.entries(game.skills).map(([id,lv])=>`<span class="chip">${SKILLS.find(s=>s.id===id).name} ${lv}</span>`).join('')||'<p class="empty-copy">ステージを突破すると、<br>新しい力を選べます。</p>';document.querySelector('#fire').textContent=game.rightPlay?status.label:auto?'自動発射中':'押している間 発射';document.querySelector('#fire').classList.toggle('active',(auto||held)&&game.phase==='playing');}
function frame(t){const dt=Math.min(.05,(t-last)/1000||0);last=t;if(game&&machine){if(game.phase==='playing'){accumulator+=dt*speed;let steps=0;while(accumulator>=1/120&&steps++<24&&game.phase==='playing'){const fixed=1/120,shotInterval=firingInterval(game,{manual}),muzzleGap=Math.min(.15,shotInterval);fireClock+=fixed;muzzleClock+=fixed;if(pendingExtras>0&&muzzleClock+1e-9>=muzzleGap){const shot=shotSettings(game,physics,{manual,power,angle});if(physics.canLaunch()&&(manual||!physics.shouldWaitToFire(game,shot.power,shot.angle))){const ball=game.fire(true);if(ball){pendingExtras--;physics.spawn(ball,shot.power,shot.angle);muzzleClock=Math.min(muzzleGap,Math.max(0,muzzleClock-muzzleGap));}}}if((auto||held)&&fireClock+1e-9>=shotInterval&&muzzleClock+1e-9>=muzzleGap){const shot=shotSettings(game,physics,{manual,power,angle});const waiting=!physics.canLaunch()||(!manual&&physics.shouldWaitToFire(game,shot.power,shot.angle));const ball=waiting?null:game.fire();if(ball){fireClock=Math.min(shotInterval,Math.max(0,fireClock-shotInterval));muzzleClock=Math.min(muzzleGap,Math.max(0,muzzleClock-muzzleGap));physics.spawn(ball,shot.power,shot.angle);sfx.play('shot');}else fireClock=Math.min(fireClock,shotInterval);}else if(!(auto||held))fireClock=Math.min(fireClock,shotInterval);physics.step(fixed,game);game.tick(fixed);processEvents();accumulator-=fixed;}}else accumulator=0;machine.render(game);reelDisplay?.update(game);if(game.presentation)battle?.render(game);updateCinema();moonTraces?.update(game);hudTick+=dt;if(hudTick>.09){updateHUD();hudTick=0;}}}
document.addEventListener('visibilitychange',()=>{held=false;if(document.hidden&&game?.phase==='playing')pause();});window.addEventListener('blur',()=>{held=false;});document.addEventListener('keydown',e=>{if(e.key==='Tab'&&modal){const buttons=[...modal.querySelectorAll('button:not(:disabled),input')];const first=buttons[0],end=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();end?.focus();}else if(!e.shiftKey&&document.activeElement===end){e.preventDefault();first?.focus();}}if(e.key==='Escape'&&game?.phase==='playing')pause();});
// Read-only diagnostics for repeatable local QA; no gameplay mutations are exposed.
window.__pachinko={renderer:()=>machine?.diagnostics()??null,trajectories:()=>physics?.balls.map(b=>({id:b.id,x:b.x,y:b.y,vx:b.vx,vy:b.vy})),audio:()=>({enabled:sfx.enabled,state:sfx.context?.state||'locked',active:sfx.voices.size,cues:[...sfx.history]}),snapshot:()=>game?{time:game.time,fireRate:game.fireRate,stageStartStock:game.stageStartStock,target:game.target,lowerBorder:game.lowerBorder,zeroTime:game.zeroTime,payoutMultiplier:game.payoutMultiplier,phase:game.phase,stock:game.stock,total:game.total,ticketEstimate:game.ticketEstimate,stage:game.stage,cleared:game.cleared,balls:physics.balls.length,skills:{...game.skills},jackpot:game.jackpot?{...game.jackpot}:null,rush:game.rush?{...game.rush}:null,normalHolds:game.normalHolds?.length??0,rushHolds:game.rushHolds?.length??0,rightPlay:game.rightPlay,practice:game.practice,endless:game.endless,debug:game.debug,accounting:game.accounting,physics:physics.diagnostics?.()??null,pendingExtras,draws:game.draws,lastRush:game.lastRush?{...game.lastRush}:null,pityCount:game.pityCount,pityLimit:game.rules.pityLimit,balance:game.stock-game.initial,historyLength:game.balanceHistory.length,holds:game.queue,spinActive:game.spinActive,stopTimer:game.stopTimer,reels:reelState(game).numbers,presentation:game.presentation?{...game.presentation}:null}:null};
home();
